def abi_variant_for(venue, role, registry_name, source_commit):
    """Select a concrete source variant before inspecting a log topic."""
    if not all(isinstance(value, str) for value in (venue, role, registry_name, source_commit)):
        raise TabulariumError('Wildcat ABI context fields are not strings')
    matches = []
    for ident, variant in VARIANTS.items():
        if {'generation': venue, 'role': role} not in variant['bindings']:
            continue
        if _SOURCE_PINS[variant['input'].rsplit('/', 1)[-1]] != source_commit:
            continue
        contract = variant['contract']
        if registry_name == contract or registry_name.startswith(contract + ' ') or registry_name.startswith(contract + ':'):
            matches.append(ident)
    if len(matches) > 1:
        raise TabulariumError('Wildcat ABI context selects ambiguous concrete variants')
    return matches[0] if matches else None


def hex_bytes(value, size=None):
    if not isinstance(value, str) or not _HEX.fullmatch(value):
        raise TabulariumError('Wildcat ABI value is not hexadecimal bytes')
    if len(value) > 2 + MAX_DATA_BYTES * 2:
        raise TabulariumError('Wildcat ABI data exceeds its byte budget')
    data = bytes.fromhex(value[2:])
    if size is not None and len(data) != size:
        raise TabulariumError('Wildcat ABI value has the wrong byte length')
    return data


def _static(word, abi_type):
    number = int.from_bytes(word, 'big')
    if abi_type == 'address':
        if number >> 160:
            raise TabulariumError('Wildcat ABI address has nonzero padding')
        return '0x' + word[12:].hex()
    if abi_type == 'bool':
        if number not in (0, 1):
            raise TabulariumError('Wildcat ABI boolean is neither zero nor one')
        return bool(number)
    if not re.fullmatch(r'uint(?:8|16|24|32|80|128|256)', abi_type):
        raise TabulariumError('Wildcat concrete ABI contains an unsupported parameter type')
    if number >= 1 << int(abi_type[4:]):
        raise TabulariumError('Wildcat ABI unsigned integer exceeds its declared width')
    # Native quantities retain all uint256 precision as decimal strings.
    return str(number)


def decode_log(variant_id, raw):
    """Return accepted definition and named values, or None for an unknown topic."""
    if variant_id not in VARIANTS:
        raise TabulariumError('Wildcat ABI variant is not accepted')
    if not isinstance(raw, dict) or not isinstance(raw.get('topics'), list):
        raise TabulariumError('Wildcat log topics are not an array')
    topics = raw['topics']
    if not 1 <= len(topics) <= 4:
        raise TabulariumError('Wildcat log has an invalid topic count')
    topic0 = '0x' + hex_bytes(topics[0], 32).hex()
    definition = VARIANTS[variant_id]['events'].get(topic0)
    if definition is None:
        # Unknown data is preserved, but its representation is still bounded.
        hex_bytes(raw.get('data'))
        for topic in topics[1:]:
            hex_bytes(topic, 32)
        return None
    abi = definition['abi']
    parameters = abi['inputs']
    indexed = [item for item in parameters if item['indexed']]
    data_parameters = [item for item in parameters if not item['indexed']]
    if abi['anonymous'] or len(topics) != 1 + len(indexed):
        raise TabulariumError('Wildcat supported event has the wrong topic count')
    data = hex_bytes(raw.get('data'))
    head_bytes = 32 * len(data_parameters)
    if len(data) < head_bytes or len(data) % 32:
        raise TabulariumError('Wildcat supported event has a truncated ABI head')
    values = {}
    for parameter, word in zip(indexed, topics[1:]):
        values[parameter['name']] = _static(hex_bytes(word, 32), parameter['type'])
    tail_end = head_bytes
    for position, parameter in enumerate(data_parameters):
        word = data[position * 32:(position + 1) * 32]
        if parameter['type'] != 'string':
            values[parameter['name']] = _static(word, parameter['type'])
            continue
        offset = int.from_bytes(word, 'big')
        if offset != tail_end or offset + 32 > len(data):
            raise TabulariumError('Wildcat supported ABI string offset is not canonical')
        length = int.from_bytes(data[offset:offset + 32], 'big')
        tail_end = offset + 32 + ((length + 31) // 32) * 32
        if length > MAX_STRING_BYTES or tail_end > len(data):
            raise TabulariumError('Wildcat supported ABI string exceeds its byte budget')
        if any(data[offset + 32 + length:tail_end]):
            raise TabulariumError('Wildcat supported ABI string has nonzero padding')
        try:
            values[parameter['name']] = data[offset + 32:offset + 32 + length].decode('utf-8')
        except UnicodeDecodeError as error:
            raise TabulariumError('Wildcat supported ABI string is not UTF-8') from error
    if tail_end != len(data):
        raise TabulariumError('Wildcat supported event has trailing ABI bytes')
    signature = abi['name'] + '(' + ','.join(item['type'] for item in parameters) + ')'
    if signature != definition['signature'] or '0x' + keccak256(signature.encode()).hex() != topic0:
        raise TabulariumError('Wildcat accepted ABI definition does not match its topic')
    return definition, values
